const tt=k=>TXT[i18n.lang]?.[k]??TXT.en[k]??k;
const TIER={en:{wood:'Wooden',stone:'Stone',copper:'Copper',iron:'Iron',crystal:'Crystal'},ko:{wood:'나무',stone:'돌',copper:'구리',iron:'철',crystal:'크리스탈'},ja:{wood:'木',stone:'石',copper:'銅',iron:'鉄',crystal:'クリスタル'},zh:{wood:'木',stone:'石',copper:'铜',iron:'铁',crystal:'水晶'}};
const TOOL={en:{Sword:' Sword',Pickaxe:' Pickaxe',Axe:' Axe'},ko:{Sword:' 검',Pickaxe:' 곡괭이',Axe:' 도끼'},ja:{Sword:'の剣',Pickaxe:'のつるはし',Axe:'の斧'},zh:{Sword:'剑',Pickaxe:'镐',Axe:'斧'}};
const SPECIAL={en:{hammer:'Hammer',researchBench:'Research Bench',wallItem:'Wall',generatorItem:'Generator',relayItem:'Repair Relay',depotItem:'Supply Depot',plank:'Board',cord:'Cord',metalPlate:'Metal Plate',circuit:'Circuit',armorShell:'Reinforced Shell',workbench:'Workbench'},ko:{hammer:'망치',researchBench:'연구 작업대',wallItem:'벽',generatorItem:'발전기',relayItem:'수리 중계기',depotItem:'보급고',plank:'판자',cord:'끈',metalPlate:'금속판',circuit:'회로',armorShell:'강화 외피',workbench:'제작대'},ja:{hammer:'ハンマー',researchBench:'研究台',wallItem:'壁',generatorItem:'発電機',relayItem:'修理リレー',depotItem:'補給所',plank:'板',cord:'ひも',metalPlate:'金属板',circuit:'回路',armorShell:'強化外殻',workbench:'作業台'},zh:{hammer:'锤子',researchBench:'研究台',wallItem:'墙',generatorItem:'发电机',relayItem:'维修中继器',depotItem:'补给站',plank:'木板',cord:'绳',metalPlate:'金属板',circuit:'电路',armorShell:'强化外壳',workbench:'工作台'}};
const resourceKeys=Object.keys(RESOURCES),lang=()=>TIER[i18n.lang]?i18n.lang:'en';
function itemLabel(id){if(resourceKeys.includes(id))return base(`res_${id}`);if(SPECIAL[lang()]?.[id])return SPECIAL[lang()][id];const m=id.match(/^(wood|stone|copper|iron|crystal)(Sword|Pickaxe|Axe)$/);if(m)return `${TIER[lang()][m[1]]}${TOOL[lang()][m[2]]}`;return itemName(id)}
function buildingName(type){if(['wall','generator','relay','depot'].includes(type))return base(`build_${type}`);return itemLabel(type)}
function researchName(id){return base(`research_${id}`)}
function zoneName(id){return base(`zone_${id}`)}
let S=null,canvas=null,ctx=null,U={},bound=false,runSerial=0;
window.addEventListener('rbf-start-game',e=>start(e.detail));
function stackBonus(){return S?.tech?.has('logistics')?16:0}
function makePlayer(name,ai=false,color='#e9f4ff',index=0){const roles=['vanguard','gatherer','builder','support'];return{name,ai,color,role:ai?roles[index%roles.length]:'player',activity:'idle',x:WORLD.heart.x+rand(-55,55),y:WORLD.heart.y+105+rand(-30,30),radius:ai?12:PLAYER.radius,maxHp:ai?118:PLAYER.maxHp,hp:ai?118:PLAYER.maxHp,dead:false,deadAt:0,cd:0,dashCd:0,dashT:0,inventory:starterInventory(),bubble:null,think:rand(.1,.35),goal:null,repairCd:0}}
function start(detail){if(detail.language&&detail.language!==i18n.lang)i18n.set(detail.language);const runId=++runSerial;root.innerHTML=markup();root.classList.remove('hidden');canvas=root.querySelector('#gameCanvas');ctx=canvas.getContext('2d');U=Object.fromEntries([...root.querySelectorAll('[id]')].map(e=>[e.id,e]));const aiCount=Math.max(0,Math.min(AI_PLAYERS.length,Number(detail.room?.aiCount)||0));S={runId,detail,last:performance.now(),time:0,keys:new Set(),mouse:{x:640,y:360},camera:{x:0,y:0},phase:'prep',phaseTime:WORLD.prepSeconds,wave:0,score:0,bank:Object.fromEntries(resourceKeys.map(k=>[k,0])),tech:new Set(),heart:{...WORLD.heart,hp:WORLD.heart.maxHp,maxHp:WORLD.heart.maxHp},player:makePlayer(detail.playerName||'User1'),ais:AI_PLAYERS.slice(0,aiCount).map((a,i)=>makePlayer(a.name,true,a.accent,i)),buildings:[],nodes:[],enemies:[],drops:[],particles:[],selectedHotbar:0,buildType:null,modal:null,cursor:null,armor:null,paused:false,over:false,waypoint:null,recipeQuery:'',recipeCategory:'all',cache:{},avatar:null,chat:[],wipeTimer:0};Object.assign(S.bank,{wood:12,stone:10,crystal:3});if(detail.custom){const img=new Image();img.onload=()=>{if(S?.runId===runId)S.avatar=img};img.src=detail.custom}seedWorld();bindGlobal();bindInstance();renderHotbar();renderHUD(true);renderChat();if(detail.settings?.showTips!==false&&!localStorage.getItem('rbf.onboarded.2'))showTutorial();requestAnimationFrame(now=>loop(now,runId))}
function markup(){return `<main class="game-shell"><div class="game-top"><div class="hud-strip"><div class="hud-card"><span>HEART</span><strong id="heartHp"></strong><div class="meter"><i id="heartBar"></i></div></div><div class="hud-card"><span>HP</span><strong id="playerHp"></strong><div class="meter"><i id="playerBar"></i></div></div><div class="hud-card"><span>WAVE</span><strong id="waveText">0</strong><small id="phaseText"></small></div><div class="hud-card"><span>ZONE</span><strong id="zoneText"></strong></div><div class="hud-card"><span>DASH</span><strong id="dashText">${tt('ready')}</strong><div class="meter"><i id="dashBar"></i></div></div><div class="hud-card"><span>SCORE</span><strong id="scoreText">0</strong></div></div><div class="row"><button id="helpBtn" class="btn">?</button><button id="pauseBtn" class="btn">${tt('pause')}</button></div></div><section class="game-layout"><aside class="side-panel compact-panel"><h3>${tt('holding')}</h3><div id="heldItem" class="selected-tool"></div><p class="muted">${tt('toolHint')}</p><p class="muted">${tt('dismantle')}</p><h3>TEAM STORAGE</h3><div id="resourceGrid" class="resource-grid"></div></aside><section class="arena-wrap"><canvas id="gameCanvas" width="1280" height="720"></canvas><div id="objective" class="objective-card"></div><div id="buildDock" class="build-dock hidden"></div><div id="interactionHint" class="interaction-hint"></div><div id="banner" class="banner hidden"></div><div id="toast" class="toast hidden"></div><div id="hotbar" class="hotbar"></div><div id="gameModal" class="inventory-modal hidden"></div><div id="cursorStack" class="cursor-stack hidden"></div><div id="deathPanel" class="death-panel hidden"></div><div id="overlay" class="overlay-panel hidden"></div></section><aside class="side-panel"><h3>${base('squad')}</h3><div id="squadList"></div><h3>${tt('inventory')}</h3><button id="inventoryButton" class="btn full">I · ${tt('inventory')}</button><div id="itemInspect" class="selection-info"></div><p class="muted">${tt('spawnClear')}</p></aside></section><div id="miniMapBox" class="mini-map-box"><canvas id="miniMap" width="320" height="190"></canvas><div class="mini-map-footer"><small>${base('map')}</small><div class="row"><button id="clearWaypoint" class="btn tiny hidden">${tt('clearWaypoint')}</button><button id="miniClose" class="btn tiny hidden">×</button></div></div></div><div class="chat-box"><div id="chatLog" class="chat-log"></div><input id="chatInput" class="chat-input" maxlength="180" placeholder="${base('chat')} · Enter"></div></main>`}
const all=()=>S?[S.player,...S.ais]:[],live=()=>all().filter(p=>!p.dead),held=()=>S.player.inventory[S.selectedHotbar],heldDef=()=>ITEM_DEFS[held()?.id],zoneAt=(x,y)=>ZONES.find(z=>x>=z.x&&x<z.x+z.w&&y>=z.y&&y<z.y+z.h)||ZONES[4],carried=p=>p.inventory.reduce((n,s)=>n+(s&&ITEM_DEFS[s.id]?.kind==='resource'?s.count:0),0);
function safePoint(z){for(let tries=0;tries<50;tries++){const p={x:rand(z.x+45,z.x+z.w-45),y:rand(z.y+45,z.y+z.h-45)};if(dist(p,S.heart)<145)continue;if(S.buildings.every(b=>dist(p,b)>WORLD.nodeSpawnClearance))return p}return null}
function seedWorld(){S.nodes=[];for(const z of ZONES)for(let i=0;i<(z.id==='heartlands'?20:15);i++){const p=safePoint(z);if(!p)continue;const type=z.nodeTypes[Math.floor(Math.random()*z.nodeTypes.length)],d=NODE_TYPES[type];S.nodes.push({type,zone:z.id,x:p.x,y:p.y,radius:d.radius,hp:d.hp,maxHp:d.hp,color:d.color,respawn:0})}}
function respawnNode(n){const z=ZONES.find(z=>z.id===n.zone),p=safePoint(z);if(!p){n.respawn=S.time+3;return}const type=z.nodeTypes[Math.floor(Math.random()*z.nodeTypes.length)],d=NODE_TYPES[type];Object.assign(n,{type,x:p.x,y:p.y,radius:d.radius,hp:d.hp,maxHp:d.hp,color:d.color,respawn:0})}
function nearest(arr,p,range,filter=()=>true){let best=null,bd=range;for(const o of arr)if(filter(o)){const d=dist(p,o);if(d<bd){best=o;bd=d}}return best}
function drop(id,count,x,y){if(!ITEM_DEFS[id]||count<=0)return;S.drops.push({id,count,x:x+rand(-10,10),y:y+rand(-10,10),radius:8,bob:Math.random()*Math.PI*2})}
function pickup(p){for(let i=S.drops.length-1;i>=0;i--){const d=S.drops[i];if(!p.dead&&dist(p,d)<p.radius+d.radius+12){const left=addItem(p.inventory,d.id,d.count,stackBonus());if(!left)S.drops.splice(i,1);else d.count=left;if(p===S.player)renderHotbar()}}}
function harvest(n,p=S.player){const d=NODE_TYPES[n.type];drop(d.resource,d.amount,n.x,n.y);if(d.secondary&&Math.random()<d.secondaryChance)drop(d.secondary,Math.max(1,Math.floor(d.amount*.35)),n.x,n.y);n.hp=0;n.respawn=S.time+11+Math.random()*8;if(p===S.player)S.score+=2}
function toolPower(node,def){if(!def?.toolType)return{damage:4,cooldown:.8,match:false};const match=def.toolType===NODE_TYPES[node.type].tool;return{damage:(match?28:6)*(def.gather||1),cooldown:Math.max(.22,def.cooldown||.6),match}}
function worldMouse(){return{x:S.mouse.x+S.camera.x,y:S.mouse.y+S.camera.y}}
function actionTargets(){const w=worldMouse(),enemyAim=nearest(S.enemies,w,46,e=>e.hp>0&&e.spawnDelay<=0&&dist(S.player,e)<=PLAYER.actionRange),nodeAim=nearest(S.nodes,w,52,n=>n.hp>0&&dist(S.player,n)<=PLAYER.actionRange);return{enemyAim,nodeAim,w}}
function damageEnemy(e,dmg){if(!e||e.hp<=0)return;e.hp=Math.max(0,e.hp-dmg);e.hitUntil=S.time+.12;burst(e.x,e.y,'#d9efff',5)}
function attackOrGather(){if(S.player.dead||S.paused||S.modal||S.over||S.player.cd>0)return;const def=heldDef(),{enemyAim,nodeAim}=actionTargets();let enemy=enemyAim,node=nodeAim;if(!enemy&&def?.toolType==='sword')enemy=nearest(S.enemies,S.player,PLAYER.actionRange,e=>e.hp>0&&e.spawnDelay<=0);if(!node&&['axe','pickaxe'].includes(def?.toolType))node=nearest(S.nodes,S.player,PLAYER.actionRange,n=>n.hp>0&&NODE_TYPES[n.type].tool===def.toolType);if(enemy&&(enemyAim||def?.toolType==='sword'||!node)){damageEnemy(enemy,def?.damage||6);S.player.cd=def?.cooldown||.72;return}if(node){const power=toolPower(node,def);node.hp=Math.max(0,node.hp-power.damage);S.player.cd=power.cooldown;if(node.hp<=0)harvest(node);return}if(enemy){damageEnemy(enemy,def?.damage||6);S.player.cd=def?.cooldown||.72}}
function rect(b){return{x:b.gx*grid(),y:b.gy*grid(),w:b.gw*grid(),h:b.gh*grid()}}
function circleRect(x,y,r,R){const nx=clamp(x,R.x,R.x+R.w),ny=clamp(y,R.y,R.y+R.h);return Math.hypot(x-nx,y-ny)<r}
function blockingBuilding(x,y,r,ignore=null){return S.buildings.find(b=>b!==ignore&&b.hp>0&&circleRect(x,y,r,rect(b)))||null}
function attemptMove(e,vx,vy,step){const nx=clamp(e.x+vx*step,e.radius,WORLD.width-e.radius),ny=clamp(e.y+vy*step,e.radius,WORLD.height-e.radius);if(!blockingBuilding(nx,ny,e.radius)){e.x=nx;e.y=ny;return true}let moved=false;if(!blockingBuilding(nx,e.y,e.radius)){e.x=nx;moved=true}if(!blockingBuilding(e.x,ny,e.radius)){e.y=ny;moved=true}return moved}
function moveSmart(e,dx,dy,speed,dt){if(e.dead)return false;const n=norm(dx,dy),step=speed*dt;if(attemptMove(e,n.x,n.y,step))return true;for(const a of [Math.PI/4,-Math.PI/4,Math.PI/2,-Math.PI/2]){const ca=Math.cos(a),sa=Math.sin(a),vx=n.x*ca-n.y*sa,vy=n.x*sa+n.y*ca;if(attemptMove(e,vx,vy,step))return true}return false}
function footprint(type,x,y){const b=BUILDINGS[type];return{gx:Math.floor(x/grid()-(b.gridW-1)/2),gy:Math.floor(y/grid()-(b.gridH-1)/2),gw:b.gridW,gh:b.gridH}}
function cells(f){const a=[];for(let y=0;y<f.gh;y++)for(let x=0;x<f.gw;x++)a.push(`${f.gx+x},${f.gy+y}`);return a}
function placementCheck(f){const R={x:f.gx*grid(),y:f.gy*grid(),w:f.gw*grid(),h:f.gh*grid()},occ=new Set(S.buildings.filter(b=>b.hp>0).flatMap(cells));if(f.gx<0||f.gy<0||R.x+R.w>WORLD.width||R.y+R.h>WORLD.height)return{ok:false,reason:'bounds',R};if(cells(f).some(c=>occ.has(c)))return{ok:false,reason:'occupied',R};if(circleRect(S.heart.x,S.heart.y,S.heart.radius+42,R))return{ok:false,reason:'heart',R};for(const p of[...live(),...S.enemies.filter(e=>e.spawnDelay<=0&&e.hp>0)])if(circleRect(p.x,p.y,p.radius+2,R))return{ok:false,reason:'entity',R};return{ok:true,R}}
function findStructureItem(type){const id=BUILDINGS[type]?.item;return S.player.inventory.findIndex(s=>s?.id===id)}
function consumeSlot(i,n=1){const s=S.player.inventory[i];if(!s)return false;s.count-=n;if(s.count<=0)S.player.inventory[i]=null;return true}
function place(type,x,y){const spec=BUILDINGS[type];if(!spec)return;const def=heldDef();if(def?.toolType!=='hammer')return toast(tt('needHammer'));if(spec.research&&!S.tech.has(spec.research))return toast(tt('locked'));const idx=findStructureItem(type);if(idx<0)return toast(tt('noStructure'));const f=footprint(type,x,y),check=placementCheck(f);if(!check.ok)return toast(tt('buildInvalid'));consumeSlot(idx);const mul=type==='wall'?1+(S.tech.has('wallI')?.35:0)+(S.tech.has('wallII')?.35:0):1,hp=spec.hp*mul,b={type,...f,x:(f.gx+f.gw/2)*grid(),y:(f.gy+f.gh/2)*grid(),hp,maxHp:hp,color:spec.color,cd:0};S.buildings.push(b);for(const n of S.nodes)if(n.hp>0&&dist(n,b)<WORLD.nodeSpawnClearance){n.hp=0;n.respawn=S.time+6+Math.random()*4}burst(b.x,b.y,spec.color,12);renderHotbar();renderBuildDock();renderHUD(true)}
function buildingAt(x,y){return [...S.buildings].reverse().find(b=>{const R=rect(b);return b.hp>0&&x>=R.x&&x<=R.x+R.w&&y>=R.y&&y<=R.y+R.h})}
function dismantleAt(x,y){if(heldDef()?.toolType!=='hammer')return;const b=buildingAt(x,y);if(!b)return;const id=BUILDINGS[b.type]?.item;if(id){const left=addItem(S.player.inventory,id,1,stackBonus());if(left)drop(id,left,S.player.x,S.player.y)}S.buildings.splice(S.buildings.indexOf(b),1);S.buildType=null;toast(tt('dismantled'));renderHotbar();renderBuildDock();renderHUD(true)}
function buildingNear(type,range=PLAYER.stationRange){return nearest(S.buildings,S.player,range,b=>b.type===type&&b.hp>0)}
function nearestDepositPoint(p){const heartRange=S.heart.radius+PLAYER.depositRange;if(dist(p,S.heart)<=heartRange)return S.heart;return nearest(S.buildings,p,170,b=>b.type==='depot'&&b.hp>0&&dist(p,b)<=BUILDINGS.depot.depositRadius)}
function deposit(p,silent=false){if(p.dead||!nearestDepositPoint(p))return false;let total=0;for(let i=0;i<p.inventory.length;i++){const s=p.inventory[i];if(s&&ITEM_DEFS[s.id]?.kind==='resource'){S.bank[s.id]=(S.bank[s.id]||0)+s.count;total+=s.count;p.inventory[i]=null}}if(total){if(p===S.player&&!silent){toast(`${tt('depositDone')}: ${total}`);S.score+=Math.min(50,total)}renderHotbar();renderHUD(true);return true}return false}
function reviveCost(){const m=S.tech.has('rescue')?.7:1;return{crystal:Math.ceil(6*m),herb:Math.ceil(8*m),iron:Math.ceil(4*m)}}
function canRevive(){return Object.entries(reviveCost()).every(([k,v])=>(S.bank[k]||0)>=v)}
function payBank(cost){for(const[k,v]of Object.entries(cost))S.bank[k]-=v}
function revive(p){if(!p?.dead)return false;if(!canRevive()){if(p===S.player)toast(tt('reviveNeed'));return false}payBank(reviveCost());p.dead=false;p.hp=Math.ceil(p.maxHp*(S.tech.has('rescue')?.8:.62));p.x=S.heart.x+rand(-45,45);p.y=S.heart.y+95+rand(-18,18);p.goal=null;p.activity='idle';banner(`${p.name} · ${tt('revive')}`);renderDeath();renderHUD(true);return true}
function damageActor(p,dmg){if(!p||p.dead)return;const armor=p===S.player&&S.armor?.id==='armorShell'?(ITEM_DEFS.armorShell.defense||0):0;p.hp=Math.max(0,p.hp-dmg*(1-armor));if(p.hp<=0){p.dead=true;p.deadAt=S.time;p.goal=null;p.activity='down';pushSystem(`${p.name} · ${tt('down')}`);renderDeath();renderHUD(true)}}
function interaction(){const dead=nearest(S.ais,S.player,78,a=>a.dead);if(dead&&canRevive())return{type:'revive',target:dead};const r=buildingNear('researchBench'),w=buildingNear('workbench');if(r)return{type:'research',building:r};if(w)return{type:'craft',building:w};if(carried(S.player)>0&&nearestDepositPoint(S.player))return{type:'deposit'};return null}
function openContext(){if(S.modal)return closeModal();const hit=interaction();if(hit?.type==='revive')return revive(hit.target);if(hit?.type==='research')return openResearch();if(hit?.type==='craft')return openCraft();if(hit?.type==='deposit')return deposit(S.player);openInventory()}
function slotHtml(s,i,cls=''){const d=s&&ITEM_DEFS[s.id];return `<button class="slot item-slot ${cls}" data-slot="${i}" title="${s?esc(itemLabel(s.id)):''}">${s?`<b class="item-icon">${d?.icon||'?'}</b><span class="item-short">${esc(itemLabel(s.id)).slice(0,10)}</span><em>${s.count>1?s.count:''}</em>`:''}<small>${i<9?i+1:''}</small></button>`}
function renderHotbar(){if(!S||!U.hotbar)return;U.hotbar.innerHTML=S.player.inventory.slice(0,9).map((s,i)=>slotHtml(s,i,S.selectedHotbar===i?'selected':'')).join('');U.hotbar.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>selectHotbar(Number(b.dataset.slot)));renderHeld();renderBuildDock()}
function selectHotbar(i){S.selectedHotbar=clamp(i,0,8);if(heldDef()?.toolType!=='hammer')S.buildType=null;renderHotbar()}
function renderHeld(){const s=held(),d=heldDef();if(!s){U.heldItem.innerHTML='<span class="muted">—</span>';U.itemInspect.innerHTML='<span class="muted">—</span>';return}const stat=d?.toolType?`<small>${d.toolType.toUpperCase()} · DMG ${d.damage??'-'} · CD ${d.cooldown??'-'}s · EFF ${d.gather??1}×</small>`:`<small>${esc(d?.kind||'')}</small>`;U.heldItem.innerHTML=`<b>${d?.icon||'?'} ${esc(itemLabel(s.id))}</b>${stat}`;U.itemInspect.innerHTML=`<b>${esc(itemLabel(s.id))}</b>${stat}<p>${tt('left')}<br>${tt('right')}</p>`}
function renderBuildDock(){if(!S||!U.buildDock)return;const d=heldDef();if(d?.toolType!=='hammer'){S.buildType=null;U.buildDock.classList.add('hidden');return}const choices=Object.entries(BUILDINGS).filter(([type,spec])=>findStructureItem(type)>=0&&(!spec.research||S.tech.has(spec.research)));U.buildDock.classList.remove('hidden');U.buildDock.innerHTML=`<span>${tt('build')}</span>${choices.map(([type,spec])=>{const s=S.player.inventory[findStructureItem(type)];return`<button class="btn ${S.buildType===type?'primary':''}" data-build="${type}">${spec.icon||ITEM_DEFS[spec.item]?.icon||'▧'} ${esc(buildingName(type))} ×${s?.count||0}</button>`}).join('')||`<small>${tt('noStructure')}</small>`}<button class="btn danger" data-build-cancel>× ${tt('cancel')}</button>`;U.buildDock.querySelectorAll('[data-build]').forEach(b=>b.onclick=e=>{e.stopPropagation();S.buildType=b.dataset.build;renderBuildDock()});U.buildDock.querySelector('[data-build-cancel]').onclick=e=>{e.stopPropagation();S.buildType=null;renderBuildDock()}}
function openInventory(){S.modal='inventory';renderInventoryModal()}
function openCraft(){if(!buildingNear('workbench'))return toast(tt('stationTooFar'));S.modal='craft';renderCraftModal()}
function openResearch(){if(!buildingNear('researchBench'))return toast(tt('stationTooFar'));S.modal='research';renderResearchModal()}
function returnCursor(){if(!S.cursor)return;const left=addItem(S.player.inventory,S.cursor.id,S.cursor.count,stackBonus());if(left)drop(S.cursor.id,left,S.player.x,S.player.y);S.cursor=null;renderCursor();renderHotbar()}
function closeModal(){returnCursor();S.modal=null;U.gameModal.classList.add('hidden');U.gameModal.innerHTML=''}
function modalShell(title,body){U.gameModal.classList.remove('hidden');U.gameModal.innerHTML=`<div class="inventory-card advanced-inventory"><div class="inventory-title"><h2>${title}</h2><button class="btn" data-close>×</button></div>${body}</div>`;U.gameModal.querySelector('[data-close]').onclick=closeModal;U.gameModal.oncontextmenu=e=>e.preventDefault()}
function renderInventoryModal(){modalShell(tt('inventory'),`<div class="inventory-help"><span>${tt('left')}</span><span>${tt('right')}</span><span>${tt('shift')}</span><span>${tt('double')}</span><span>${tt('outside')}</span></div><div class="armor-slot"><b>ARMOR</b><button class="slot item-slot" id="armorSlot">${S.armor?`${ITEM_DEFS[S.armor.id]?.icon||'◈'} <span>${esc(itemLabel(S.armor.id))}</span>`:'—'}</button></div><div class="inventory-grid">${S.player.inventory.map((s,i)=>slotHtml(s,i)).join('')}</div>`);bindInventorySlots();U.gameModal.querySelector('#armorSlot').onmousedown=e=>{e.preventDefault();armorClick(e.button)}}
function armorClick(button){if(button!==0)return;if(S.cursor){if(ITEM_DEFS[S.cursor.id]?.kind!=='armor')return;const old=S.armor;S.armor={id:S.cursor.id,count:1};S.cursor=old?{...old}:null}else if(S.armor){S.cursor={...S.armor};S.armor=null}renderInventoryModal();renderCursor();renderHeld()}
function bindInventorySlots(){U.gameModal.querySelectorAll('[data-slot]').forEach(el=>{const i=Number(el.dataset.slot);el.onmousedown=e=>{e.preventDefault();slotClick(i,e.button,e.shiftKey)};el.ondblclick=e=>{e.preventDefault();collectMatching(i)}});U.gameModal.onmousedown=e=>{if(e.target.closest('.inventory-card'))return;if(S.cursor){dropCursor(e.button===2);renderCurrentModal()}}}
function slotClick(i,button,shift){const slot=S.player.inventory[i];if(shift&&button===0&&slot&&ITEM_DEFS[slot.id]?.kind==='armor'&&!S.armor){S.armor={...slot};S.player.inventory[i]=null;renderCurrentModal();renderHotbar();return}if(shift&&button===0)return quickMove(i);if(button===0){if(!S.cursor&&slot){S.cursor={...slot};S.player.inventory[i]=null}else if(S.cursor&&!slot){S.player.inventory[i]=S.cursor;S.cursor=null}else if(S.cursor&&slot?.id===S.cursor.id){const lim=stackLimit(slot.id,stackBonus()),move=Math.min(lim-slot.count,S.cursor.count);slot.count+=move;S.cursor.count-=move;if(S.cursor.count<=0)S.cursor=null}else if(S.cursor&&slot){const tmp={...slot};S.player.inventory[i]=S.cursor;S.cursor=tmp}}else if(button===2){if(!S.cursor&&slot){const take=Math.ceil(slot.count/2);S.cursor={id:slot.id,count:take};slot.count-=take;if(slot.count<=0)S.player.inventory[i]=null}else if(S.cursor&&!slot){S.player.inventory[i]={id:S.cursor.id,count:1};if(--S.cursor.count<=0)S.cursor=null}else if(S.cursor&&slot?.id===S.cursor.id&&slot.count<stackLimit(slot.id,stackBonus())){slot.count++;if(--S.cursor.count<=0)S.cursor=null}}renderCurrentModal();renderCursor();renderHotbar()}
function quickMove(i){const s=S.player.inventory[i];if(!s)return;const fromHot=i<9,start=fromHot?9:0,end=fromHot?36:9,limit=stackLimit(s.id,stackBonus());let left=s.count;for(let j=start;j<end&&left;j++){const d=S.player.inventory[j];if(d?.id===s.id&&d.count<limit){const n=Math.min(limit-d.count,left);d.count+=n;left-=n}}for(let j=start;j<end&&left;j++)if(!S.player.inventory[j]){const n=Math.min(limit,left);S.player.inventory[j]={id:s.id,count:n};left-=n}if(left)S.player.inventory[i].count=left;else S.player.inventory[i]=null;renderCurrentModal();renderHotbar()}
function collectMatching(i){const source=S.player.inventory[i];if(!S.cursor&&source){S.cursor={...source};S.player.inventory[i]=null}if(!S.cursor)return;const lim=stackLimit(S.cursor.id,stackBonus());for(let j=0;j<S.player.inventory.length&&S.cursor.count<lim;j++){const s=S.player.inventory[j];if(s?.id===S.cursor.id){const n=Math.min(s.count,lim-S.cursor.count);S.cursor.count+=n;s.count-=n;if(s.count<=0)S.player.inventory[j]=null}}renderCurrentModal();renderCursor();renderHotbar()}
function dropCursor(one){if(!S.cursor)return;const n=one?1:S.cursor.count;drop(S.cursor.id,n,S.player.x,S.player.y);S.cursor.count-=n;if(S.cursor.count<=0)S.cursor=null;renderCursor()}
function renderCursor(){if(!S||!U.cursorStack)return;if(!S.cursor){U.cursorStack.classList.add('hidden');return}const d=ITEM_DEFS[S.cursor.id];U.cursorStack.classList.remove('hidden');U.cursorStack.innerHTML=`<b>${d?.icon||'?'} ${esc(itemLabel(S.cursor.id))}</b><span>${S.cursor.count}</span>`}
function countAvailable(id){let n=S.bank[id]||0;for(const s of S.player.inventory)if(s?.id===id)n+=s.count;return n}
function canRecipe(r){return Object.entries(r.ingredients).every(([id,n])=>countAvailable(id)>=n)}
function consumeIngredient(id,n){for(let i=0;i<S.player.inventory.length&&n;i++){const s=S.player.inventory[i];if(s?.id===id){const take=Math.min(n,s.count);s.count-=take;n-=take;if(s.count<=0)S.player.inventory[i]=null}}if(n){const take=Math.min(n,S.bank[id]||0);S.bank[id]-=take;n-=take}return n===0}
function recipeLocked(r){const structure=ITEM_DEFS[r.out.id]?.structure,spec=structure&&BUILDINGS[structure];return !!(spec?.research&&!S.tech.has(spec.research))}
function craftRecipe(id,many=false){const r=RECIPES.find(x=>x.id===id);if(!r||recipeLocked(r))return toast(tt('locked'));let crafts=0,total=0;do{if(!canRecipe(r)||!canFitItem(S.player.inventory,r.out.id,r.out.count,stackBonus()))break;for(const[k,v]of Object.entries(r.ingredients))consumeIngredient(k,v);addItem(S.player.inventory,r.out.id,r.out.count,stackBonus());crafts++;total+=r.out.count}while(many&&crafts<64);if(!crafts)return toast(tt('noMaterials'));toast(`${tt('crafted')}: ${itemLabel(r.out.id)} ×${total}`);renderCraftModal();renderHotbar();renderHUD(true)}
function recipeList(){const q=S.recipeQuery.trim().toLowerCase();return RECIPES.filter(r=>r.station==='workbench'&&(S.recipeCategory==='all'||r.category===S.recipeCategory)&&(!q||`${itemLabel(r.out.id)} ${r.id}`.toLowerCase().includes(q)))}
function categoryName(cat){return tt(cat==='all'?'categoryAll':cat==='material'?'categoryMaterial':cat==='tool'?'categoryTool':cat==='weapon'?'categoryWeapon':cat==='building'?'categoryBuilding':cat==='station'?'categoryStation':'categoryArmor')}
function renderCraftModal(){if(!buildingNear('workbench'))return closeModal();const list=recipeList(),cats=['all','material','tool','weapon','building','station','armor'];modalShell(`▧ ${tt('craft')}`,`<div class="craft-layout"><aside class="recipe-book"><input id="recipeSearch" class="input" placeholder="${tt('search')}" value="${esc(S.recipeQuery)}"><div class="recipe-tabs">${cats.map(cat=>`<button class="btn tiny ${S.recipeCategory===cat?'primary':''}" data-cat="${cat}">${categoryName(cat)}</button>`).join('')}</div><div class="recipe-list">${list.map(r=>{const locked=recipeLocked(r),ok=canRecipe(r);return`<button class="recipe-card ${locked?'locked':''}" data-recipe="${r.id}"><span>${ITEM_DEFS[r.out.id]?.icon||'?'} ${esc(itemLabel(r.out.id))} ${r.out.count>1?`×${r.out.count}`:''}</span><small>${Object.entries(r.ingredients).map(([k,v])=>{const have=countAvailable(k);return`<span class="ingredient ${have<v?'missing':''}">${esc(itemLabel(k))} ${have}/${v}</span>`}).join('')}</small><em>${locked?tt('locked'):(ok?'✓':'')}</em></button>`}).join('')||`<p class="muted">${tt('noMaterials')}</p>`}</div></aside><section class="craft-detail"><div class="section-heading"><h3>${tt('inventory')}</h3><span class="badge">${tt('available')}: ${resourceKeys.reduce((n,k)=>n+(S.bank[k]||0),0)}</span></div><div class="inventory-grid">${S.player.inventory.map((s,i)=>slotHtml(s,i)).join('')}</div><p class="muted">${tt('left')} · ${tt('right')} · Shift+${tt('craft')} = MAX</p></section></div>`);const search=U.gameModal.querySelector('#recipeSearch');search.oninput=e=>{S.recipeQuery=e.target.value;renderCraftModal();requestAnimationFrame(()=>{const n=U.gameModal.querySelector('#recipeSearch');n?.focus();n?.setSelectionRange(n.value.length,n.value.length)})};U.gameModal.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{S.recipeCategory=b.dataset.cat;renderCraftModal()});U.gameModal.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=e=>craftRecipe(b.dataset.recipe,e.shiftKey));bindInventorySlots()}
function researchAffordable(r){return Object.entries(r.cost).every(([k,v])=>(S.bank[k]||0)>=v)}
function doResearch(id){const r=RESEARCH[id];if(!r||S.tech.has(id)||(r.requires||[]).some(x=>!S.tech.has(x)))return;if(!researchAffordable(r))return toast(tt('noMaterials'));payBank(r.cost);S.tech.add(id);if(id==='corePlating'){S.heart.maxHp+=350;S.heart.hp=Math.min(S.heart.maxHp,S.heart.hp+350)}if(id==='wallI'||id==='wallII')for(const b of S.buildings.filter(b=>b.type==='wall')){const ratio=b.hp/b.maxHp;b.maxHp=BUILDINGS.wall.hp*(1+(S.tech.has('wallI')?.35:0)+(S.tech.has('wallII')?.35:0));b.hp=b.maxHp*ratio}toast(tt('researchDone'));renderResearchModal();renderBuildDock();renderHUD(true)}
function branchName(id){return tt(id==='defense'?'branchDefense':id==='support'?'branchSupport':id==='logistics'?'branchLogistics':'branchExploration')}
function renderResearchModal(){if(!buildingNear('researchBench'))return closeModal();const branches=['defense','support','logistics','exploration'];modalShell(`⌬ ${tt('research')}`,`<div class="research-tree">${branches.map(branch=>{const nodes=Object.entries(RESEARCH).filter(([,r])=>r.branch===branch);if(!nodes.length)return'';return`<section class="research-branch"><h3>${branchName(branch)}</h3>${nodes.map(([id,r])=>{const done=S.tech.has(id),locked=(r.requires||[]).some(x=>!S.tech.has(x)),ok=researchAffordable(r);return`<button class="research-node ${done?'done':''} ${locked?'locked':''}" data-research="${id}" ${done||locked?'disabled':''}><b>${esc(researchName(id))}</b><small>${Object.entries(r.cost).map(([k,v])=>`<span class="ingredient ${(S.bank[k]||0)<v?'missing':''}">${esc(itemLabel(k))} ${Math.floor(S.bank[k]||0)}/${v}</span>`).join('')}</small><span>${done?'✓':locked?tt('locked'):ok?'READY':tt('need')}</span></button>`}).join('')}</section>`}).join('')}</div>`);U.gameModal.querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>doResearch(b.dataset.research))}
function renderCurrentModal(){if(S.modal==='inventory')renderInventoryModal();else if(S.modal==='craft')renderCraftModal();else if(S.modal==='research')renderResearchModal()}
function nearestRepairable(a,range=500){return nearest(S.buildings,a,range,b=>b.hp>0&&b.hp<b.maxHp*.86)}
function nearestDepositForAI(a){const depots=S.buildings.filter(b=>b.type==='depot'&&b.hp>0);let best=S.heart,bd=dist(a,S.heart);for(const d of depots){const dd=dist(a,d);if(dd<bd){best=d;bd=dd}}return best}
function planAI(a){a.think=.35+Math.random()*.2;const threat=nearest(S.enemies,a,a.role==='vanguard'?620:430,e=>e.spawnDelay<=0&&e.hp>0);if(threat)return a.goal={type:'fight',target:threat};const down=all().find(p=>p!==a&&p.dead);if(down&&canRevive()&&(a.role==='support'||a.role==='vanguard'))return a.goal={type:'revive',target:down};if(carried(a)>=16)return a.goal={type:'deposit',target:nearestDepositForAI(a)};if((a.role==='builder'||a.role==='support')&&(S.bank.wood>0||S.bank.stone>0)){const damaged=nearestRepairable(a);if(damaged)return a.goal={type:'repair',target:damaged}}const n=nearest(S.nodes,a,a.role==='gatherer'?760:560,x=>x.hp>0);a.goal=n?{type:'gather',target:n}:{type:'home',target:S.heart}}
function aiGather(a,n,dt){const d=NODE_TYPES[n.type],def=a.inventory.find(s=>ITEM_DEFS[s?.id]?.toolType===d.tool),tool=ITEM_DEFS[def?.id],power=toolPower(n,tool);n.hp=Math.max(0,n.hp-power.damage*dt*2.1);if(n.hp<=0)harvest(n,a)}
function updateAI(dt){for(const a of S.ais){a.cd=Math.max(0,a.cd-dt);a.repairCd=Math.max(0,a.repairCd-dt);a.think-=dt;if(a.dead)continue;pickup(a);if(deposit(a,true)){a.goal=null;a.activity='idle'}if(a.think<=0||!a.goal||a.goal.target?.hp<=0)planAI(a);const g=a.goal;if(!g)continue;if(g.type==='fight'){a.activity='defending';const e=g.target;if(dist(a,e)<80&&a.cd<=0){damageEnemy(e,18+(a.role==='vanguard'?5:0));a.cd=.58}else moveSmart(a,e.x-a.x,e.y-a.y,a.role==='vanguard'?168:148,dt)}else if(g.type==='revive'){a.activity='reviving';if(dist(a,g.target)<72){if(revive(g.target))a.goal=null}else moveSmart(a,g.target.x-a.x,g.target.y-a.y,145,dt)}else if(g.type==='deposit'){a.activity='returning';if(nearestDepositPoint(a)){deposit(a,true);a.goal=null}else moveSmart(a,g.target.x-a.x,g.target.y-a.y,138,dt)}else if(g.type==='repair'){a.activity='repairing';const b=g.target;if(dist(a,b)<82){if(a.repairCd<=0){const key=S.bank.wood>0?'wood':S.bank.stone>0?'stone':null;if(key){S.bank[key]--;b.hp=Math.min(b.maxHp,b.hp+24);a.repairCd=.65;renderHUD(true)}else a.goal=null}}else moveSmart(a,b.x-a.x,b.y-a.y,132,dt)}else if(g.type==='gather'){a.activity='gathering';if(dist(a,g.target)<82)aiGather(a,g.target,dt);else moveSmart(a,g.target.x-a.x,g.target.y-a.y,a.role==='gatherer'?142:128,dt)}else{a.activity='idle';moveSmart(a,S.heart.x-a.x,S.heart.y+95-a.y,112,dt)}}}
function spawnEnemy(type,delay=0){const d=ENEMIES[type],side=Math.floor(Math.random()*4),mul={easy:.86,normal:1,hard:1.2}[S.detail.room?.difficulty]||1,scale=(1+S.wave*.08)*mul;let x=side===0?5:side===1?WORLD.width-5:rand(0,WORLD.width),y=side===2?5:side===3?WORLD.height-5:rand(0,WORLD.height);S.enemies.push({type,x,y,radius:d.radius,hp:d.hp*scale,maxHp:d.hp*scale,speed:d.speed,damage:d.damage*mul,reward:d.reward,color:d.color,spawnDelay:delay,cd:0,hitUntil:0})}
function beginWave(){S.wave++;S.phase='wave';S.phaseTime=WORLD.baseWaveSeconds+S.wave*2;for(let i=0;i<Math.min(44,6+S.wave*3);i++){const r=Math.random();spawnEnemy(S.wave>2&&r<.15?'brute':r<.36?'runner':'grunt',i*.22)}if(S.wave%5===0)spawnEnemy('boss',1.5);banner(`${base('wave')} ${S.wave}`);pushSystem(`${base('wave')} ${S.wave}`)}
function updateEnemies(dt){for(const e of S.enemies){if(e.spawnDelay>0){e.spawnDelay-=dt;continue}if(e.hp<=0)continue;e.cd=Math.max(0,e.cd-dt);const nearby=nearest(live(),e,145),target=nearby||S.heart,dir=norm(target.x-e.x,target.y-e.y),step=e.speed*dt,block=blockingBuilding(e.x+dir.x*step,e.y+dir.y*step,e.radius+2);if(block){if(e.cd<=0){const breach=ENEMIES[e.type]?.breach||1;block.hp=Math.max(0,block.hp-e.damage*breach*(S.tech.has('fortify')?.8:1));e.cd=.7;if(block.hp<=0){if(['workbench','researchBench'].includes(block.type))drop(BUILDINGS[block.type].item,1,block.x,block.y);burst(block.x,block.y,'#9f8d78',10)}}continue}const range=(target.radius||PLAYER.radius)+e.radius+5;if(dist(e,target)<range){if(e.cd<=0){if(target===S.heart){S.heart.hp=Math.max(0,S.heart.hp-e.damage);if(S.heart.hp<=0)finish('heart')}else damageActor(target,e.damage);e.cd=.72}}else moveSmart(e,target.x-e.x,target.y-e.y,e.speed,dt)}for(let i=S.enemies.length-1;i>=0;i--){const e=S.enemies[i];if(e.hp<=0){S.bank.crystal+=e.reward;S.score+=e.reward*10;S.enemies.splice(i,1)}}S.buildings=S.buildings.filter(b=>b.hp>0)}
function support(dt){if(S.tech.has('fieldRepair'))for(const r of S.buildings.filter(b=>b.type==='relay'&&b.hp>0)){const powered=S.buildings.some(g=>g.type==='generator'&&g.hp>0&&dist(g,r)<(BUILDINGS.generator.powerRadius||320));if(powered)for(const b of S.buildings)if(b!==r&&dist(b,r)<(BUILDINGS.relay.repairRadius||195))b.hp=Math.min(b.maxHp,b.hp+10*dt)}}
function phase(dt){if(S.phase==='prep'||S.phase==='recovery'){S.phaseTime-=dt;if(S.phaseTime<=0){S.phase='warning';S.phaseTime=WORLD.warningSeconds;banner('⚠');pushSystem(base('incoming'))}}else if(S.phase==='warning'){S.phaseTime-=dt;if(S.phaseTime<=0)beginWave()}else if(S.phase==='wave'){S.phaseTime=Math.max(0,S.phaseTime-dt);if(!S.enemies.length){S.phase='recovery';S.phaseTime=WORLD.recoverySeconds;S.score+=50+S.wave*10;for(const p of live())p.hp=Math.min(p.maxHp,p.hp+p.maxHp*.12);banner(base('recovery'));pushSystem(base('recovery'))}}}
function updatePlayer(dt){const p=S.player;p.cd=Math.max(0,p.cd-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.dashT=Math.max(0,p.dashT-dt);if(p.dead)return;const dx=(S.keys.has('KeyD')?1:0)-(S.keys.has('KeyA')?1:0),dy=(S.keys.has('KeyS')?1:0)-(S.keys.has('KeyW')?1:0);if(dx||dy)moveSmart(p,dx,dy,p.dashT>0?PLAYER.dashSpeed:PLAYER.speed,dt);pickup(p)}
function update(dt){if(!S||S.paused||S.modal||S.over)return;S.time+=dt;updatePlayer(dt);updateAI(dt);for(const n of S.nodes)if(n.hp<=0&&n.respawn&&S.time>=n.respawn)respawnNode(n);phase(dt);updateEnemies(dt);support(dt);for(const p of S.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}S.particles=S.particles.filter(p=>p.life>0);if(!live().length){S.wipeTimer+=dt;if(!canRevive()&&S.wipeTimer>1.5)finish('wipe')}else S.wipeTimer=0;renderDeath()}
function bindGlobal(){if(bound)return;bound=true;window.addEventListener('mousemove',e=>{if(U.cursorStack){U.cursorStack.style.left=`${e.clientX+14}px`;U.cursorStack.style.top=`${e.clientY+14}px`}});window.addEventListener('keydown',e=>{if(!S)return;if(document.activeElement===U.chatInput){if(e.key==='Escape')U.chatInput.blur();return}if(e.code==='Escape'){if(S.modal)return closeModal();togglePause();e.preventDefault();return}if(S.over||S.paused)return;if(e.code==='KeyI'){if(S.modal==='inventory')closeModal();else if(!S.modal)openInventory();e.preventDefault();return}if(S.modal)return;if(e.code==='KeyE'){openContext();e.preventDefault();return}if(e.code==='KeyF'){deposit(S.player);e.preventDefault();return}if(/^Digit[1-9]$/.test(e.code)){selectHotbar(Number(e.code.slice(-1))-1);return}if(e.code==='Space'&&!S.player.dead&&!S.player.dashCd){S.player.dashCd=PLAYER.dashCooldown;S.player.dashT=PLAYER.dashDuration;burst(S.player.x,S.player.y,'#8ddcff',14);e.preventDefault();return}if(e.code==='Enter'){U.chatInput.focus();e.preventDefault();return}S.keys.add(e.code)});window.addEventListener('keyup',e=>S?.keys.delete(e.code));document.addEventListener('visibilitychange',()=>{if(document.hidden&&S&&!S.over&&!S.modal){S.paused=true;renderOverlay()}})}
function bindInstance(){canvas.onmousemove=e=>{const r=canvas.getBoundingClientRect();S.mouse.x=(e.clientX-r.left)*canvas.width/r.width;S.mouse.y=(e.clientY-r.top)*canvas.height/r.height};canvas.onmousedown=e=>{if(S.modal||S.paused||S.over)return;const w=worldMouse();if(e.button===2){dismantleAt(w.x,w.y);return}if(e.button!==0)return;if(heldDef()?.toolType==='hammer'&&S.buildType)place(S.buildType,w.x,w.y);else attackOrGather()};canvas.oncontextmenu=e=>e.preventDefault();U.inventoryButton.onclick=()=>{if(S.modal==='inventory')closeModal();else if(!S.modal)openInventory()};U.pauseBtn.onclick=togglePause;U.helpBtn.onclick=()=>{S.paused=true;renderOverlay(true)};U.chatInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();sendChat(U.chatInput.value);U.chatInput.value='';U.chatInput.blur()}};U.miniMap.onclick=miniClick;U.miniMapBox.onclick=e=>{if(e.target===U.miniMap||e.target.closest('button'))return;if(!U.miniMapBox.classList.contains('expanded'))U.miniMapBox.classList.add('expanded')};U.clearWaypoint.onclick=e=>{e.stopPropagation();S.waypoint=null;U.clearWaypoint.classList.add('hidden')};U.miniClose.onclick=e=>{e.stopPropagation();U.miniMapBox.classList.remove('expanded');U.miniClose.classList.add('hidden')}}
function miniClick(e){if(!U.miniMapBox.classList.contains('expanded')){U.miniMapBox.classList.add('expanded');U.miniClose.classList.remove('hidden');return}const r=U.miniMap.getBoundingClientRect();S.waypoint={x:(e.clientX-r.left)/r.width*WORLD.width,y:(e.clientY-r.top)/r.height*WORLD.height};U.clearWaypoint.classList.remove('hidden');toast(tt('waypoint'))}
function togglePause(){if(S.over||S.modal)return;S.paused=!S.paused;renderOverlay()}
function renderOverlay(help=false){U.overlay.classList.toggle('hidden',!S.paused&&!S.over);if(!S.paused||S.over)return;U.overlay.innerHTML=`<div class="overlay-card"><h2>${help?tt('help'):tt('pause')}</h2><p>${help?tt('tutorial'):`WASD · ${tt('interact')} · ${tt('bag')} · F · ${tt('deposit')} · Space · DASH · Enter · CHAT`}</p><p class="muted">${tt('toolHint')}</p><div class="row"><button class="btn primary" data-resume>${tt('resume')}</button><button class="btn" data-return>${tt('return')}</button></div></div>`;U.overlay.querySelector('[data-resume]').onclick=()=>{S.paused=false;renderOverlay()};U.overlay.querySelector('[data-return]').onclick=returnLobby}
function showTutorial(){S.paused=true;U.overlay.classList.remove('hidden');U.overlay.innerHTML=`<div class="overlay-card tutorial-card"><span class="eyebrow">RE:BUILDFRONT</span><h2>${tt('help')}</h2><p>${tt('tutorial')}</p><div class="tutorial-keys"><span>WASD</span><span>E</span><span>I</span><span>F</span><span>SPACE</span></div><button class="btn primary" data-tutorial>${tt('got')}</button></div>`;U.overlay.querySelector('[data-tutorial]').onclick=()=>{localStorage.setItem('rbf.onboarded.2','1');S.paused=false;U.overlay.classList.add('hidden')}}
function returnLobby(){if(!S)return;returnCursor();S=null;root.innerHTML='';root.classList.add('hidden');window.dispatchEvent(new Event('rbf-return-lobby'))}
function finish(reason='heart'){if(!S||S.over)return;S.over=true;S.paused=false;U.deathPanel.classList.add('hidden');U.overlay.classList.remove('hidden');U.overlay.innerHTML=`<div class="overlay-card"><span class="eyebrow">RUN COMPLETE</span><h2>${reason==='wipe'?tt('teamWipe'):base('heartLost')}</h2><div class="summary-grid"><div><span>${base('wave')}</span><b>${S.wave}</b></div><div><span>${base('score')}</span><b>${S.score}</b></div></div><div class="row"><button class="btn primary" data-retry>${base('restart')}</button><button class="btn" data-return>${tt('return')}</button></div></div>`;U.overlay.querySelector('[data-retry]').onclick=()=>start(S.detail);U.overlay.querySelector('[data-return]').onclick=returnLobby}
function renderDeath(){if(!S||!U.deathPanel)return;const dead=S.player.dead,cost=reviveCost(),affordable=canRevive(),sig=`${dead}|${S.over}|${affordable}|${Object.entries(cost).map(([k,v])=>`${k}:${Math.floor(S.bank[k]||0)}:${v}`).join('|')}`;if(S.cache.death===sig)return;S.cache.death=sig;U.deathPanel.classList.toggle('hidden',!dead||S.over);if(!dead||S.over)return;U.deathPanel.innerHTML=`<div class="death-card"><h2>${tt('down')}</h2><p>${Object.entries(cost).map(([k,v])=>`${esc(itemLabel(k))} ${Math.floor(S.bank[k]||0)}/${v}`).join(' · ')}</p><button id="selfRevive" class="btn primary" ${affordable?'':'disabled'}>${tt('revive')}</button>${!affordable?`<small>${tt('reviveNeed')}</small>`:''}<button id="giveUp" class="btn">${tt('giveUp')}</button></div>`;U.deathPanel.querySelector('#selfRevive').onclick=()=>revive(S.player);U.deathPanel.querySelector('#giveUp').onclick=()=>finish('wipe')}
function activityText(a){return tt(a.activity==='repairing'?'repairing':a.activity==='gathering'?'gathering':a.activity==='defending'?'defending':a.activity==='returning'?'returning':a.activity==='reviving'?'reviving':'idle')}
function setText(id,v){if(S.cache[id]===String(v))return;S.cache[id]=String(v);U[id].textContent=v}
function setWidth(id,v){const x=`${clamp(v,0,100)}%`;if(S.cache[id]===x)return;S.cache[id]=x;U[id].style.width=x}
function renderHUD(force=false){if(!S)return;if(force)S.cache={};setText('heartHp',`${Math.ceil(S.heart.hp)} / ${S.heart.maxHp}`);setWidth('heartBar',S.heart.hp/S.heart.maxHp*100);setText('playerHp',`${Math.ceil(S.player.hp)} / ${S.player.maxHp}`);setWidth('playerBar',S.player.hp/S.player.maxHp*100);setText('waveText',S.wave);setText('phaseText',S.phase==='wave'&&S.phaseTime<=0?tt('overtime'):`${S.phase} · ${Math.ceil(Math.max(0,S.phaseTime))}s`);setText('zoneText',zoneName(zoneAt(S.player.x,S.player.y).id));setText('scoreText',S.score);setText('dashText',S.player.dashCd?`${S.player.dashCd.toFixed(1)}s`:tt('ready'));setWidth('dashBar',(1-S.player.dashCd/PLAYER.dashCooldown)*100);const count=S.enemies.filter(e=>e.spawnDelay<=0).length,obj=`${S.phase}|${count}|${carried(S.player)}|${Math.ceil(S.phaseTime)}`;if(S.cache.objective!==obj){S.cache.objective=obj;const msg=S.phase==='prep'?tt('prep'):S.phase==='warning'?tt('warning'):S.phase==='wave'?tt('wave'):tt('recovery');U.objective.innerHTML=`<span class="eyebrow">${tt('objective')}</span><b>${msg}</b><small>${tt('remaining')}: ${count} · ${tt('carrying')}: ${carried(S.player)}${S.phase==='wave'&&!S.phaseTime&&count?` · ${tt('overtime')}`:''}</small>`}const rs=resourceKeys.map(k=>`${k}:${Math.floor(S.bank[k])}`).join('|');if(force||S.cache.resources!==rs){S.cache.resources=rs;U.resourceGrid.innerHTML=resourceKeys.map(k=>`<div class="resource-chip"><span style="color:${RESOURCES[k].color}">${RESOURCES[k].icon}</span><b>${esc(itemLabel(k))}</b><strong>${Math.floor(S.bank[k])}</strong></div>`).join('')}const ss=all().map(p=>`${p.name}:${Math.ceil(p.hp)}:${p.dead}:${p.activity}`).join('|');if(force||S.cache.squad!==ss){S.cache.squad=ss;U.squadList.innerHTML=all().map(p=>`<div class="squad-row ${p===S.player?'player-self':''}"><div><b>${p===S.player?base('you'):esc(p.name)}</b><small>${p.ai?activityText(p):''}</small></div><div class="squad-hp"><i style="width:${clamp(p.hp/p.maxHp*100,0,100)}%"></i></div><span>${p.dead?tt('down'):`${Math.ceil(p.hp)}/${p.maxHp}`}</span></div>`).join('')}const hit=interaction(),buildMode=heldDef()?.toolType==='hammer'&&S.buildType;let hint=buildMode?tt('buildReady'):hit?.type==='craft'?`E · ${tt('craft')}`:hit?.type==='research'?`E · ${tt('research')}`:hit?.type==='deposit'?`E/F · ${tt('deposit')}`:hit?.type==='revive'?`E · ${tt('revive')}`:`${tt('interact')} · ${tt('bag')}`;if(S.cache.hint!==hint){S.cache.hint=hint;U.interactionHint.textContent=hint}}
function sendChat(raw){const text=String(raw||'').trim().slice(0,180);if(!text)return;const whisper=text.match(/^\/w\s+(\S+)\s+(.+)$/i);if(whisper){const target=all().find(p=>p.name.toLowerCase()===whisper[1].toLowerCase());if(!target)return toast(base('playerNotFound'));S.chat.push({type:'whisper',sender:S.player.name,target:target.name,text:whisper[2]});S.player.bubble={text:whisper[2],until:S.time+4,type:'whisper'}}else{S.chat.push({type:'global',sender:S.player.name,text});S.player.bubble={text,until:S.time+4,type:'global'}}S.chat=S.chat.slice(-60);renderChat()}
function pushSystem(text){if(!S)return;S.chat.push({type:'system',sender:'SYSTEM',text:String(text)});S.chat=S.chat.slice(-60);renderChat()}
function renderChat(){if(!S||!U.chatLog)return;U.chatLog.innerHTML=S.chat.slice(-10).map(m=>`<div class="chat-row ${m.type}"><b>${m.type==='whisper'?'[W] ':''}${esc(m.sender)}${m.target?` → ${esc(m.target)}`:''}</b><span>${esc(m.text)}</span></div>`).join('');U.chatLog.scrollTop=U.chatLog.scrollHeight}
function drawNode(n){const d=NODE_TYPES[n.type],resource=RESOURCES[d.resource];ctx.fillStyle=n.color;ctx.beginPath();if(d.tool==='axe'){ctx.arc(n.x,n.y,n.radius,0,Math.PI*2)}else{ctx.moveTo(n.x,n.y-n.radius);ctx.lineTo(n.x+n.radius,n.y);ctx.lineTo(n.x,n.y+n.radius);ctx.lineTo(n.x-n.radius,n.y);ctx.closePath()}ctx.fill();ctx.fillStyle='#f4fbff';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(resource?.icon||'?',n.x,n.y+4);if(n.hp<n.maxHp){ctx.fillStyle='rgba(0,0,0,.7)';ctx.fillRect(n.x-18,n.y-n.radius-9,36,4);ctx.fillStyle='#79dfa4';ctx.fillRect(n.x-18,n.y-n.radius-9,36*n.hp/n.maxHp,4)}if(dist(S.player,n)<135){ctx.fillStyle='rgba(5,10,15,.76)';ctx.fillRect(n.x-32,n.y+n.radius+6,64,16);ctx.fillStyle='#eaf6ff';ctx.font='9px system-ui';ctx.fillText(itemLabel(d.resource),n.x,n.y+n.radius+17)}ctx.textAlign='left'}
function drawBuilding(b){const R=rect(b),spec=BUILDINGS[b.type];ctx.fillStyle=b.color;ctx.fillRect(R.x+3,R.y+3,R.w-6,R.h-6);ctx.strokeStyle='rgba(255,255,255,.18)';ctx.strokeRect(R.x+3,R.y+3,R.w-6,R.h-6);ctx.fillStyle='#fff';ctx.font=`bold ${Math.min(18,10+R.w/18)}px system-ui`;ctx.textAlign='center';ctx.fillText(spec.icon||'▧',b.x,b.y+4);ctx.font='9px system-ui';ctx.fillText(buildingName(b.type),b.x,b.y+18);ctx.textAlign='left';if(b.hp<b.maxHp){ctx.fillStyle='rgba(0,0,0,.75)';ctx.fillRect(R.x,R.y-11,R.w,6);ctx.fillStyle='#79dfa4';ctx.fillRect(R.x,R.y-11,R.w*b.hp/b.maxHp,6)}}
function drawPlayer(p){ctx.globalAlpha=p.dead?.32:1;if(p===S.player&&S.avatar&&!p.dead){ctx.save();ctx.beginPath();ctx.arc(p.x,p.y,p.radius,0,Math.PI*2);ctx.clip();ctx.drawImage(S.avatar,p.x-p.radius,p.y-p.radius,p.radius*2,p.radius*2);ctx.restore();ctx.strokeStyle='#dff6ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,p.radius,0,Math.PI*2);ctx.stroke()}else{ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.radius,0,Math.PI*2);ctx.fill();ctx.fillStyle='#162330';ctx.beginPath();ctx.arc(p.x-4,p.y-3,2,0,Math.PI*2);ctx.arc(p.x+4,p.y-3,2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.fillStyle='#fff';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText(p.name,p.x,p.y-p.radius-10);if(p.hp<p.maxHp&&!p.dead){ctx.fillStyle='rgba(0,0,0,.65)';ctx.fillRect(p.x-18,p.y+p.radius+5,36,4);ctx.fillStyle='#79dfa4';ctx.fillRect(p.x-18,p.y+p.radius+5,36*p.hp/p.maxHp,4)}if(p.bubble&&p.bubble.until>S.time){const text=String(p.bubble.text).slice(0,36),w=Math.min(200,Math.max(70,ctx.measureText(text).width+18));ctx.fillStyle=p.bubble.type==='whisper'?'#5b3c78':'#162534';ctx.fillRect(p.x-w/2,p.y-p.radius-42,w,23);ctx.fillStyle='#fff';ctx.fillText(text,p.x,p.y-p.radius-26)}ctx.textAlign='left'}
function drawEnemy(e){ctx.fillStyle=e.hitUntil>S.time?'#f6d4d4':e.color;ctx.beginPath();ctx.arc(e.x,e.y,e.radius,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font=`bold ${Math.max(9,e.radius*.7)}px system-ui`;ctx.textAlign='center';ctx.fillText(ENEMIES[e.type]?.icon||'●',e.x,e.y+4);ctx.textAlign='left';if(e.hp<e.maxHp||dist(S.player,e)<120){ctx.fillStyle='rgba(0,0,0,.75)';ctx.fillRect(e.x-e.radius,e.y-e.radius-9,e.radius*2,4);ctx.fillStyle='#ff8585';ctx.fillRect(e.x-e.radius,e.y-e.radius-9,e.radius*2*e.hp/e.maxHp,4)}}
function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);const focus=S.player.dead?S.heart:S.player;S.camera.x=clamp(focus.x-canvas.width/2,0,WORLD.width-canvas.width);S.camera.y=clamp(focus.y-canvas.height/2,0,WORLD.height-canvas.height);ctx.save();ctx.translate(-S.camera.x,-S.camera.y);for(const z of ZONES){ctx.fillStyle=z.color;ctx.fillRect(z.x,z.y,z.w,z.h);ctx.strokeStyle=z.accent;ctx.strokeRect(z.x,z.y,z.w,z.h);ctx.fillStyle='rgba(255,255,255,.38)';ctx.font='600 14px system-ui';ctx.fillText(zoneName(z.id),z.x+16,z.y+25)}if(heldDef()?.toolType==='hammer'&&S.buildType){ctx.strokeStyle='rgba(255,255,255,.055)';ctx.lineWidth=1;for(let x=0;x<=WORLD.width;x+=grid()){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,WORLD.height);ctx.stroke()}for(let y=0;y<=WORLD.height;y+=grid()){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WORLD.width,y);ctx.stroke()}}ctx.strokeStyle='rgba(114,210,255,.35)';ctx.lineWidth=8;ctx.beginPath();ctx.arc(S.heart.x,S.heart.y,S.heart.radius+7,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#72d2ff';ctx.beginPath();ctx.arc(S.heart.x,S.heart.y,S.heart.radius,0,Math.PI*2);ctx.fill();ctx.fillStyle='#08202e';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText('HEART',S.heart.x,S.heart.y+4);ctx.textAlign='left';for(const n of S.nodes)if(n.hp>0)drawNode(n);for(const d of S.drops){const def=ITEM_DEFS[d.id],res=RESOURCES[d.id];ctx.fillStyle=res?.color||'#dbe9f3';ctx.beginPath();ctx.arc(d.x,d.y+Math.sin(S.time*3+d.bob)*2,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#071018';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(def?.icon||'?',d.x,d.y+3+Math.sin(S.time*3+d.bob)*2);ctx.textAlign='left'}for(const b of S.buildings)drawBuilding(b);for(const p of all())drawPlayer(p);for(const e of S.enemies.filter(e=>e.spawnDelay<=0))drawEnemy(e);for(const p of S.particles){ctx.globalAlpha=clamp(p.life/.5,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-2,p.y-2,4,4)}ctx.globalAlpha=1;if(S.waypoint){ctx.strokeStyle='#ffe28a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(S.waypoint.x,S.waypoint.y,13,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffe28a';ctx.font='10px system-ui';ctx.fillText('◆',S.waypoint.x-4,S.waypoint.y+3)}if(heldDef()?.toolType==='hammer'&&S.buildType){const w=worldMouse(),f=footprint(S.buildType,w.x,w.y),check=placementCheck(f),R=check.R;ctx.fillStyle=check.ok?'rgba(90,220,150,.3)':'rgba(255,80,90,.3)';ctx.strokeStyle=check.ok?'#75dfa3':'#ff7878';ctx.lineWidth=2;ctx.fillRect(R.x,R.y,R.w,R.h);ctx.strokeRect(R.x,R.y,R.w,R.h)}ctx.restore();drawMap()}
function drawMap(){if(!U.miniMap)return;const m=U.miniMap.getContext('2d'),sx=320/WORLD.width,sy=190/WORLD.height;m.clearRect(0,0,320,190);for(const z of ZONES){m.fillStyle=z.color;m.fillRect(z.x*sx,z.y*sy,z.w*sx,z.h*sy);m.strokeStyle=z.accent;m.strokeRect(z.x*sx,z.y*sy,z.w*sx,z.h*sy)}m.fillStyle='#72d2ff';m.beginPath();m.arc(S.heart.x*sx,S.heart.y*sy,5,0,Math.PI*2);m.fill();for(const b of S.buildings){m.fillStyle=b.color;m.fillRect((b.x-5)*sx,(b.y-5)*sy,10*sx+2,10*sy+2)}if(S.tech.has('survey'))for(const n of S.nodes.filter(n=>n.hp>0)){m.fillStyle=RESOURCES[NODE_TYPES[n.type].resource]?.color||'#fff';m.fillRect(n.x*sx,n.y*sy,2,2)}for(const p of live()){m.fillStyle=p===S.player?'#fff':'#9de3ff';m.beginPath();m.arc(p.x*sx,p.y*sy,3,0,Math.PI*2);m.fill()}m.fillStyle='#e96b6b';for(const e of S.enemies.filter(e=>e.spawnDelay<=0)){m.beginPath();m.arc(e.x*sx,e.y*sy,2,0,Math.PI*2);m.fill()}if(S.waypoint){m.strokeStyle='#ffe28a';m.beginPath();m.arc(S.waypoint.x*sx,S.waypoint.y*sy,5,0,Math.PI*2);m.stroke()}}
function burst(x,y,color,n=8){if(S.detail.settings?.reducedMotion)return;for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=rand(30,100);S.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.5,color})}}
function toast(m){if(!U.toast)return;U.toast.textContent=m;U.toast.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>U.toast?.classList.add('hidden'),1600)}
function banner(m){if(!U.banner)return;U.banner.textContent=m;U.banner.classList.remove('hidden');clearTimeout(banner.t);banner.t=setTimeout(()=>U.banner?.classList.add('hidden'),1700)}
function loop(now,runId){if(!S||S.runId!==runId)return;const dt=Math.min(.033,Math.max(0,(now-S.last)/1000));S.last=now;update(dt);renderHUD();draw();requestAnimationFrame(next=>loop(next,runId))}
